{
  "version": "authoring-contract-v1",
  "schema": {
    "type": "object",
    "properties": {
      "shot": {
        "additionalProperties": false,
        "description": "创建请求与本地解析共用必填性，历史编译继续使用 AuthoredShot。",
        "properties": {
          "scene_id": {
            "type": "string",
            "enum": [
              "FORBIDDEN_CITY_HIGHEST_ROOF"
            ]
          },
          "scene_description": {
            "maxLength": 1600,
            "minLength": 1,
            "pattern": "\\S",
            "title": "Scene Description",
            "type": "string"
          },
          "visual_description": {
            "maxLength": 1600,
            "minLength": 1,
            "pattern": "\\S",
            "title": "Visual Description",
            "type": "string"
          },
          "camera": {
            "$ref": "#/$defs/CameraSpec"
          },
          "blocking": {
            "additionalProperties": false,
            "title": "Blocking",
            "type": "object",
            "properties": {
              "QING_FENG": {
                "$ref": "#/$defs/CharacterBlockingSpec"
              },
              "XUE_YIN": {
                "$ref": "#/$defs/CharacterBlockingSpec"
              }
            },
            "description": "角色ID到起始站位的映射。"
          },
          "start_state": {
            "$ref": "#/$defs/AuthoredContinuityState"
          },
          "end_state": {
            "$ref": "#/$defs/AuthoredContinuityState"
          },
          "story_change": {
            "maxLength": 1600,
            "minLength": 1,
            "pattern": "\\S",
            "title": "Story Change",
            "type": "string"
          },
          "story_state_after": {
            "maxLength": 1600,
            "minLength": 1,
            "pattern": "\\S",
            "title": "Story State After",
            "type": "string"
          },
          "lighting": {
            "default": "",
            "maxLength": 1600,
            "title": "Lighting",
            "type": "string"
          },
          "mood": {
            "default": "cinematic",
            "maxLength": 1600,
            "title": "Mood",
            "type": "string"
          },
          "action_plan": {
            "type": "object",
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "interaction_1": {
                    "$ref": "#/$defs/ScheduledFirstInteraction"
                  },
                  "interaction_2": {
                    "$ref": "#/$defs/ScheduledRequiredInteraction"
                  },
                  "interaction_3": {
                    "$ref": "#/$defs/ScheduledRequiredInteraction"
                  },
                  "interaction_4": {
                    "$ref": "#/$defs/ScheduledRequiredInteraction"
                  },
                  "opening": {
                    "type": "null"
                  }
                },
                "required": [
                  "interaction_1",
                  "interaction_2",
                  "interaction_3",
                  "interaction_4"
                ],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "interaction_1": {
                    "$ref": "#/$defs/ScheduledAfterOpeningInteraction"
                  },
                  "interaction_2": {
                    "$ref": "#/$defs/ScheduledRequiredInteraction"
                  },
                  "interaction_3": {
                    "$ref": "#/$defs/ScheduledRequiredInteraction"
                  },
                  "interaction_4": {
                    "$ref": "#/$defs/ScheduledRequiredInteraction"
                  },
                  "opening": {
                    "type": "object",
                    "properties": {
                      "first": {
                        "$ref": "#/$defs/ScheduledFirstPassiveUnit"
                      },
                      "following": {
                        "type": "array",
                        "maxItems": 7,
                        "items": {
                          "$ref": "#/$defs/ScheduledPassiveUnit"
                        }
                      }
                    },
                    "required": [
                      "first"
                    ],
                    "additionalProperties": false
                  }
                },
                "required": [
                  "interaction_1",
                  "interaction_2",
                  "interaction_3",
                  "interaction_4",
                  "opening"
                ],
                "additionalProperties": false
              }
            ]
          },
          "prop_roles": {
            "type": "array",
            "maxItems": 40,
            "items": {
              "additionalProperties": false,
              "properties": {
                "entity": {
                  "maxLength": 128,
                  "minLength": 1,
                  "title": "Entity",
                  "type": "string",
                  "enum": [
                    "sword_shuangxu",
                    "sword_yecuo",
                    "palace_roof_surface",
                    "upturned_eave_corner",
                    "full_moon",
                    "distant_palace_towers",
                    "loose_tile_fragment",
                    "drifting_leaf"
                  ]
                },
                "role": {
                  "enum": [
                    "visible",
                    "persistent",
                    "visible_and_persistent"
                  ],
                  "title": "Role",
                  "type": "string"
                }
              },
              "required": [
                "entity",
                "role"
              ],
              "title": "PropRole",
              "type": "object"
            }
          }
