              "dolly in",
              "dolly out",
              "pan left",
              "pan right",
              "pan",
              "tilt up",
              "tilt down",
              "tracking",
              "truck left",
              "truck right",
              "crane up",
              "crane down",
              "orbit",
              "zoom in",
              "zoom out",
              "handheld"
