          "composition": {
            "default": "",
            "title": "Composition",
            "type": "string"
          },
          "start_framing": {
            "type": "string",
            "const": "medium shot"
          },
          "end_framing": {
            "default": "",
            "title": "End Framing",
            "type": "string"
          },
          "speed": {
            "default": "fixed",
